-- ====================================================
-- DYNAMIC MENUS (3-LEVEL) + HERO SLIDES + SITE CATEGORIES
-- Additive-only migration: new columns, new tables, indexes,
-- RLS policies, and initial seeds copied from src/data.js
-- (megaMenuData sections, heroSlides x3, categorySliderItems x10).
-- No DROP / TRUNCATE / DELETE statements in this file.
-- ====================================================

-- ─── 1. Extend menu_items for 3-level mega-menu ───
-- Existing columns (title, path, icon, parent_id, roles_allowed,
-- order_index, badge, is_active, created_at) are untouched.

ALTER TABLE public.menu_items ADD COLUMN IF NOT EXISTS level INT DEFAULT 1;
ALTER TABLE public.menu_items ADD COLUMN IF NOT EXISTS section TEXT;
ALTER TABLE public.menu_items ADD COLUMN IF NOT EXISTS section_icon TEXT;
ALTER TABLE public.menu_items ADD COLUMN IF NOT EXISTS badge_variant TEXT DEFAULT 'accent';
ALTER TABLE public.menu_items ADD COLUMN IF NOT EXISTS promo_title TEXT;
ALTER TABLE public.menu_items ADD COLUMN IF NOT EXISTS promo_subtitle TEXT;
ALTER TABLE public.menu_items ADD COLUMN IF NOT EXISTS promo_image_url TEXT;
ALTER TABLE public.menu_items ADD COLUMN IF NOT EXISTS promo_cta_text TEXT;
ALTER TABLE public.menu_items ADD COLUMN IF NOT EXISTS promo_cta_path TEXT;

-- Clamp menu depth to 3 levels (idempotent guard, no DROP).
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint WHERE conname = 'menu_items_level_range'
    ) THEN
        ALTER TABLE public.menu_items
            ADD CONSTRAINT menu_items_level_range CHECK (level BETWEEN 1 AND 3);
    END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_menu_items_parent_order
    ON public.menu_items (parent_id, order_index);
CREATE INDEX IF NOT EXISTS idx_menu_items_active_order
    ON public.menu_items (is_active, order_index);

-- ─── 2. hero_slides (homepage hero carousel) ───

CREATE TABLE IF NOT EXISTS public.hero_slides (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    badge TEXT,
    title TEXT NOT NULL,
    subtitle TEXT,
    btn_text TEXT,
    btn_path TEXT DEFAULT '/products',
    bg_image_url TEXT,
    product_image_url TEXT,
    fallback_image_url TEXT,
    bg_gradient TEXT,
    price_text TEXT,
    tag TEXT,
    ribbon_text TEXT,
    order_index INT DEFAULT 0,
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

ALTER TABLE public.hero_slides ENABLE ROW LEVEL SECURITY;

-- Public read of active slides only (idempotent guard, no DROP).
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_policies
        WHERE schemaname = 'public'
          AND tablename = 'hero_slides'
          AND policyname = 'Public read active hero slides'
    ) THEN
        CREATE POLICY "Public read active hero slides"
            ON public.hero_slides FOR SELECT
            USING (is_active = true);
    END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_hero_slides_active_order
    ON public.hero_slides (is_active, order_index);

-- ─── 3. site_categories (homepage category circles) ───

CREATE TABLE IF NOT EXISTS public.site_categories (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name TEXT NOT NULL,
    image_url TEXT NOT NULL,
    path TEXT DEFAULT '/products',
    order_index INT DEFAULT 0,
    is_active BOOLEAN DEFAULT true,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

ALTER TABLE public.site_categories ENABLE ROW LEVEL SECURITY;

-- Public read of active categories only (idempotent guard, no DROP).
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_policies
        WHERE schemaname = 'public'
          AND tablename = 'site_categories'
          AND policyname = 'Public read active site categories'
    ) THEN
        CREATE POLICY "Public read active site categories"
            ON public.site_categories FOR SELECT
            USING (is_active = true);
    END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_site_categories_active_order
    ON public.site_categories (is_active, order_index);

-- ─── 4. Seeds copied verbatim from src/data.js ───
-- menu_items: fixed UUIDs + ON CONFLICT DO NOTHING (re-runnable).
-- hero_slides / site_categories: insert only when table is empty.
-- ─── menu_items seeds (3-level mega menu copied from src/data.js megaMenuData) ───

